from __future__ import annotations

import json
from datetime import date, timedelta
from pathlib import Path
from typing import Optional

import typer
from dotenv import load_dotenv

from .audit import audit_file
from .comments import add_item, draft_comments, load_inbox
from .config import get_settings
from .paths import repo_root
from .delivery import copy_instructions
from .queue import list_drafts, load_draft, save_draft
from .research import fetch_feeds, save_brief
from .poster import render_poster
from .publisher import PublishError, authorization_url, exchange_code, publish_draft
from .writer import write_day

load_dotenv(repo_root() / ".env")

app = typer.Typer(help="LinkedIn operator: research, draft, review, and explicit approved publishing.", no_args_is_help=True)


def _parse_day(value: Optional[str]) -> date:
    if not value:
        return date.today() + timedelta(days=1)
    return date.fromisoformat(value)


@app.command("research")
def research_cmd() -> None:
    """Pull allowlisted AI, framework, inference, and database feeds. Not LinkedIn."""
    items = fetch_feeds()
    path = save_brief(items)
    ok = sum(1 for i in items if i.get("title"))
    typer.echo(f"Wrote {path} ({ok} items)")


@app.command("draft-day")
def draft_day_cmd(
    day: Optional[str] = typer.Option(None, help="YYYY-MM-DD, default tomorrow IST-ish (local date+1)"),
    llm: Optional[bool] = typer.Option(
        None,
        "--llm/--no-llm",
        help="Use Gemini (default when GEMINI_API_KEY is set). --no-llm uses templates.",
    ),
    overwrite: bool = typer.Option(False),
) -> None:
    """Create Slot A and Slot B markdown drafts."""
    settings = get_settings()
    use_llm = settings.llm_configured if llm is None else llm
    if use_llm and not settings.llm_configured:
        typer.echo("Set GEMINI_API_KEY in .env (Google AI Studio) or pass --no-llm.")
        raise typer.Exit(code=1)
    if use_llm:
        typer.echo(f"Writer: {settings.resolved_provider} / {settings.llm_model}")
    target = _parse_day(day)
    research_path = repo_root() / "research" / f"{date.today().isoformat()}.md"
    if not research_path.exists():
        # fall back to newest brief
        briefs = sorted((repo_root() / "research").glob("*.md")) if (repo_root() / "research").exists() else []
        research_path = briefs[-1] if briefs else None
    paths = write_day(target, use_llm=use_llm, research_path=research_path, overwrite=overwrite)
    for path in paths:
        draft = load_draft(path)
        typer.echo(f"{path.name}  slot={draft.meta.slot} pillar={draft.meta.pillar} chars={draft.char_count} audit_ok={draft.meta.audit.get('ok')}")


@app.command("list")
def list_cmd(status: Optional[str] = typer.Option(None)) -> None:
    statuses = {status} if status else None
    rows = list_drafts(statuses=statuses)
    if not rows:
        typer.echo("No drafts.")
        raise typer.Exit()
    for draft in rows:
        typer.echo(
            f"{Path(draft.path).name:24} {draft.meta.status:10} slot={draft.meta.slot} pillar={draft.meta.pillar} chars={draft.char_count}"
        )


@app.command("audit")
def audit_cmd(path: str) -> None:
    result = audit_file(Path(path))
    typer.echo(json.dumps(result.as_dict(), indent=2))
    if not result.ok:
        raise typer.Exit(code=1)


@app.command("approve")
def approve_cmd(path: str) -> None:
    draft = load_draft(Path(path))
    result = audit_file(Path(path))
    if not result.ok:
        typer.echo("Audit failed:")
        typer.echo(json.dumps(result.as_dict(), indent=2))
        raise typer.Exit(code=1)
    draft.meta.status = "approved"
    draft.meta.audit = result.as_dict()
    save_draft(draft)
    typer.echo(f"Approved {path}")


@app.command("reject")
def reject_cmd(path: str) -> None:
    draft = load_draft(Path(path))
    draft.meta.status = "rejected"
    save_draft(draft)
    typer.echo(f"Rejected {path}")


@app.command("copy")
def copy_cmd(path: str) -> None:
    """Print the complete manual paste and evidence pack."""
    draft = load_draft(Path(path))
    typer.echo(copy_instructions(draft))


@app.command("auth-url")
def auth_url_cmd() -> None:
    """Start explicit official LinkedIn OAuth authorization."""
    try:
        typer.echo(authorization_url())
    except PublishError as exc:
        typer.echo(str(exc))
        raise typer.Exit(code=1)


@app.command("auth-exchange")
def auth_exchange_cmd(
    code: str = typer.Option(..., help="Authorization code from the local callback"),
    state: str = typer.Option(..., help="State returned with the callback"),
) -> None:
    """Exchange an OAuth code after the state check succeeds."""
    try:
        payload = exchange_code(code, state)
    except PublishError as exc:
        typer.echo(str(exc))
        raise typer.Exit(code=1)
    typer.echo(f"Saved OAuth token metadata locally ({', '.join(sorted(payload.keys()))}).")


@app.command("publish")
def publish_cmd(
    path: str,
    live: bool = typer.Option(False, "--live", help="Send the approved draft after explicit confirmation."),
) -> None:
    """Dry-run or explicitly publish one approved draft; never used by automation."""
    draft = load_draft(Path(path))
    try:
        result = publish_draft(draft, live=live, confirmed=True)
    except PublishError as exc:
        typer.echo(str(exc))
        raise typer.Exit(code=1)
    typer.echo(json.dumps(result, indent=2))
    if live and not result.get("dry_run"):
        draft.meta.status = "published"
        draft.meta.published_id = str(result.get("id") or "")
        draft.meta.audit = {**draft.meta.audit, "published_manually": True}
        save_draft(draft)


@app.command("poster")
def poster_cmd(path: str) -> None:
    """Render a minimal local PNG architecture poster for a draft."""
    source = Path(path)
    draft = load_draft(source)
    dest = repo_root() / "drafts" / "posters" / f"{source.stem}.png"
    render_poster(draft, dest)
    draft.meta.poster_path = str(dest.relative_to(repo_root()))
    save_draft(draft)
    typer.echo(dest)


@app.command("automate")
def automate_cmd(
    day: Optional[str] = typer.Option(None, help="YYYY-MM-DD, default tomorrow"),
    llm: Optional[bool] = typer.Option(None, "--llm/--no-llm"),
    overwrite: bool = typer.Option(False),
) -> None:
    """Research, draft, audit, and render posters. Never publishes."""
    settings = get_settings()
    use_llm = settings.llm_configured if llm is None else llm
    if use_llm and not settings.llm_configured:
        typer.echo("No configured LLM. Use --no-llm or set an API key.")
        raise typer.Exit(code=1)
    brief = save_brief(fetch_feeds())
    paths = write_day(_parse_day(day), use_llm=use_llm, research_path=brief, overwrite=overwrite)
    failed = False
    for path in paths:
        draft = load_draft(path)
        dest = repo_root() / "drafts" / "posters" / f"{path.stem}.png"
        render_poster(draft, dest)
        draft.meta.poster_path = str(dest.relative_to(repo_root()))
        result = audit_file(path)
        draft.meta.audit = result.as_dict()
        save_draft(draft)
        typer.echo(f"{path.name} audit_ok={result.ok} poster={draft.meta.poster_path}")
        failed = failed or not result.ok
    typer.echo("No publishing was attempted. Review drafts, then publish explicitly if desired.")
    if failed:
        raise typer.Exit(code=1)


@app.command("inbox-add")
def inbox_add_cmd(
    url: str = typer.Option(""),
    text_file: Optional[Path] = typer.Option(None, help="Pasted LinkedIn post body"),
    text: str = typer.Option("", help="Pasted post text"),
) -> None:
    body = text
    if text_file:
        body = text_file.read_text(encoding="utf-8")
    if not body.strip():
        typer.echo("Paste the post text. This command does not fetch LinkedIn.")
        raise typer.Exit(code=1)
    item = add_item(url=url, post_text=body)
    typer.echo(f"Queued {item['id']}")


@app.command("inbox-draft")
def inbox_draft_cmd(
    item_id: str = typer.Argument(...),
    llm: bool = typer.Option(False),
) -> None:
    item = draft_comments(item_id, use_llm=llm)
    typer.echo(json.dumps(item["options"], indent=2))
    typer.echo("\nSend the chosen comment yourself in the LinkedIn app.")


@app.command("inbox")
def inbox_cmd() -> None:
    for item in load_inbox():
        typer.echo(f"{item['id']}  {item.get('status')}  {item.get('url')}")


@app.command("serve")
def serve_cmd(host: Optional[str] = None, port: Optional[int] = None) -> None:
    """Local review UI; publishing requires an approved draft and explicit action."""
    try:
        import uvicorn

        from .serve import app as webapp
    except ModuleNotFoundError:
        typer.echo("Missing UI packages. In the venv run:  pip install -e '.[dev]'")
        raise typer.Exit(code=1)

    settings = get_settings()
    bind_host = host or settings.operator_host
    if bind_host not in {"127.0.0.1", "localhost", "::1"}:
        typer.echo("Refusing a non-loopback host; the review UI is local-only.")
        raise typer.Exit(code=1)
    uvicorn.run(webapp, host=bind_host, port=port or settings.operator_port)


@app.command("setup-check")
def setup_check_cmd() -> None:
    settings = get_settings()
    typer.echo(f"repo: {repo_root()}")
    typer.echo(
        f"llm: provider={settings.resolved_provider} configured={settings.llm_configured} "
        f"model={settings.llm_model} gemini_key={bool(settings.gemini_key)}"
    )
    typer.echo(
        f"linkedin app configured: {settings.linkedin_configured}; "
        f"explicit live publish enabled: {settings.live_publish_enabled}"
    )
    typer.echo("Next: operator automate --overwrite && operator serve")


if __name__ == "__main__":
    app()
